          <label>Profession<select class="form-select" name="profession"><option value="architect">Architect</option><option value="engineer">Engineer</option><option value="quantity_surveyor">Quantity surveyor</option><option value="town_planner">Town planner</option><option value="land_surveyor">Land surveyor</option><option value="landscape_architect">Landscape architect</option><option value="interior_designer">Interior designer</option><option value="construction_project_manager">Construction project manager</option></select></label>
