  function governedMeetingWorkspace() {
    const activeProject=window.__ARCHITEX_SHELL_STATE__?.projects.find(item=>item.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId);
    return `${pageHead('Architex Meetings','Schedule, consent, review and publish project meetings as governed records.','meetings','coral')}
      <div class="notice meeting-boundary"><b>Governed record boundary:</b> No live media provider is connected in this release. Recording and transcript content must come from an authorised external source, every attendee consent is explicit, and only human-reviewed outcomes can write back.</div>
      <section class="governed-meeting-layout">
        <form id="governedMeetingForm" class="panel panel-pad meeting-card"><div class="trust-card-head"><div><h2>Schedule governed meeting</h2><p>${escapeHtml(activeProject?.name||'Select a project')} · agenda, attendance and retention policy persist in MariaDB.</p></div><span class="status amber">Consent gated</span></div><div class="scaffold-grid">
          <label class="trust-wide">Meeting title<input class="form-input" name="title" required maxlength="220" value="Project coordination meeting"></label><label>Type<select class="form-select" name="meetingType"><option value="design_coordination">Design coordination</option><option value="client_brief">Client brief</option><option value="site_progress">Site progress</option><option value="commercial_review">Commercial review</option></select></label><label>Project phase<select class="form-select" name="phase"><option value="onboarding">Onboarding</option><option value="feasibility">Feasibility</option><option value="appointment" selected>Appointment</option><option value="concept_design">Concept design</option><option value="design_development">Design development</option><option value="municipal_submission">Municipal submission</option><option value="tender_procurement">Tender / procurement</option><option value="construction_execution">Construction execution</option><option value="closeout">Closeout</option></select></label><label>Starts at<input class="form-input" type="datetime-local" name="startsAt" required></label><label>Duration (minutes)<input class="form-input" type="number" name="durationMinutes" min="5" max="1440" value="45" required></label><label>Agenda item<input class="form-input" name="agendaTitle" maxlength="220" value="Review project coordination" required></label><label>Agenda owner<input class="form-input" name="agendaOwner" maxlength="180" value="Chair" required></label><label>Attendee email or identity<input class="form-input" name="attendeeIdentity" maxlength="320" value="chair@example.test" required></label><label>Attendee role<input class="form-input" name="attendeeRole" maxlength="60" value="chair" required></label><label>Retention days<input class="form-input" type="number" name="retentionDays" min="1" max="3650" value="90" required></label><label>Confidentiality<input class="form-input" name="confidentiality" maxlength="80" value="project_confidential" required></label><label class="trust-check"><input type="checkbox" name="recordingRequested" checked> Recording requested</label><label class="trust-check"><input type="checkbox" name="transcriptionRequested" checked> Transcription requested</label><label class="trust-check trust-wide"><input type="checkbox" name="consentRequired" checked> Require recorded consent from every attendee before start.</label>
        </div><div class="trust-actions"><button class="btn dark" type="submit">Schedule meeting</button><span id="governedMeetingMessage" role="status"></span></div></form>
        <section class="panel panel-pad meeting-card"><div class="trust-card-head"><div><h2>Persistent meeting lifecycle</h2><p>Scheduled → consented → live → review required → immutable published minutes.</p></div><button class="btn ghost" type="button" onclick="refreshGovernedMeetings()">Refresh</button></div><div id="governedMeetingList" class="trust-list"><div class="notice">Loading meetings…</div></div></section>
      </section>`;
  }

  async function hydrateGovernedMeetings(){const form=document.getElementById('governedMeetingForm');if(!form)return;const projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId,list=document.getElementById('governedMeetingList');if(!projectId){list.innerHTML='<div class="notice">Create or select a project before scheduling a meeting.</div>';form.querySelectorAll('input,select,button').forEach(control=>control.disabled=true);return;}try{renderGovernedMeetings(await api.get(`/meetings?projectId=${encodeURIComponent(projectId)}`));if(!form.dataset.bound){form.dataset.bound='1';form.addEventListener('submit',scheduleGovernedMeeting);}}catch(error){list.innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}if(!form.elements.startsAt.value){const date=new Date(Date.now()+3600000);date.setMinutes(Math.ceil(date.getMinutes()/15)*15,0,0);form.elements.startsAt.value=new Date(date.getTime()-date.getTimezoneOffset()*60000).toISOString().slice(0,16);}}
  async function scheduleGovernedMeeting(event){event.preventDefault();const form=event.currentTarget,v=new FormData(form),projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId,message=document.getElementById('governedMeetingMessage');message.textContent='Scheduling…';try{await api.post('/meetings',{projectId,title:v.get('title'),meetingType:v.get('meetingType'),phase:v.get('phase'),startsAt:String(v.get('startsAt')).replace('T',' ')+':00',durationMinutes:Number(v.get('durationMinutes')),agenda:[{title:v.get('agendaTitle'),owner:v.get('agendaOwner'),minutes:Number(v.get('durationMinutes'))}],attendees:[{identity:v.get('attendeeIdentity'),role:v.get('attendeeRole')}],policy:{recordingRequested:v.get('recordingRequested')==='on',transcriptionRequested:v.get('transcriptionRequested')==='on',consentRequired:v.get('consentRequired')==='on',retentionDays:Number(v.get('retentionDays')),confidentiality:v.get('confidentiality')}});message.textContent='Meeting scheduled and audited.';await hydrateGovernedMeetings();}catch(error){message.textContent=error.message;}}
  function renderGovernedMeetings(meetings){const list=document.getElementById('governedMeetingList');if(!list)return;list.innerHTML=meetings.length?meetings.map(meeting=>{const policy=meeting.policy,consentActions=meeting.status==='scheduled'&&policy.consentRequired?meeting.attendees.map(attendee=>`<button class="btn ghost" type="button" onclick="recordMeetingConsent('${escapeHtml(meeting.id)}','${escapeHtml(attendee.identity)}')">Consent: ${escapeHtml(attendee.identity)}</button>`).join(''):'';const start=meeting.status==='scheduled'?`<button class="btn dark" type="button" onclick="startGovernedMeeting('${escapeHtml(meeting.id)}')">Start governed session</button>`:'';const conclude=meeting.status==='live'?`<form class="meeting-conclude" onsubmit="concludeGovernedMeeting(event,'${escapeHtml(meeting.id)}')"><label class="trust-wide">Transcript source<textarea class="form-textarea" name="transcript" required>Decision discussed and verified by the chair.</textarea></label><label>Outcome title<input class="form-input" name="outcomeTitle" value="Issue coordinated project record" required></label><label>Outcome destination<input class="form-input" name="destination" value="project_record" required></label><button class="btn dark" type="submit">Conclude to human review</button></form>`:'';const review=meeting.status==='review_required'&&meeting.minutes?`<div class="meeting-review"><div class="notice"><b>Human outcome review required.</b> Accept or reject every extracted outcome with a reason before publishing.</div>${meeting.minutes.outcomes.map((outcome,index)=>`<article class="meeting-outcome"><b>${escapeHtml(outcome.title)}</b><span>${escapeHtml(outcome.type)} · ${escapeHtml(outcome.destination)} · source ${escapeHtml(outcome.source)}</span><div class="trust-actions"><button class="btn ghost" type="button" onclick="reviewMeetingOutcome('${escapeHtml(meeting.id)}',${index},'accepted')">Accept</button><button class="btn ghost" type="button" onclick="reviewMeetingOutcome('${escapeHtml(meeting.id)}',${index},'rejected')">Reject</button><span class="status ${outcome.state==='accepted'?'green':outcome.state==='rejected'?'amber':''}">${escapeHtml(outcome.state)}</span></div></article>`).join('')}<form class="meeting-publish" onsubmit="publishMeetingMinutes(event,'${escapeHtml(meeting.id)}')"><label class="trust-check"><input type="checkbox" name="reviewerConfirmed" required> I personally reviewed the transcript sources, minutes and every outcome.</label><label>Publication reason<input class="form-input" name="publishReason" required maxlength="500" value="Chair reviewed the exact transcript sources and outcomes."></label><button class="btn dark" type="submit">Publish immutable minutes</button></form></div>`:'';const published=meeting.status==='published'&&meeting.minutes?`<div class="notice"><b>Minutes revision ${meeting.minutes.revision} published.</b><br>SHA-256 ${escapeHtml(meeting.minutes.auditHash)}</div>`:'';return `<article class="trust-row meeting-row"><div><b>${escapeHtml(meeting.title)}</b><span>${escapeHtml(meeting.meetingType.replaceAll('_',' '))} · ${escapeHtml(meeting.startsAt)} · ${meeting.durationMinutes} min</span><small>${escapeHtml(meeting.phase)} · retention ${policy.retentionDays} days · ${escapeHtml(policy.confidentiality)}</small></div><span class="status ${meeting.status==='published'?'green':'amber'}">${escapeHtml(meeting.status.replaceAll('_',' '))}</span><div class="meeting-actions">${consentActions}${start}${conclude}${review}${published}</div></article>`;}).join(''):'<div class="notice">No governed meetings have been scheduled for this project.</div>';}
  window.refreshGovernedMeetings=hydrateGovernedMeetings;
  window.recordMeetingConsent=async function(id,identity){try{await api.post(`/meetings/${encodeURIComponent(id)}/consents`,{attendeeIdentity:identity,consented:true});showToast('Attendee consent recorded and audited.');await hydrateGovernedMeetings();}catch(error){showToast(error.message);}};
  window.startGovernedMeeting=async function(id){try{await api.post(`/meetings/${encodeURIComponent(id)}/start`,{});showToast('Governed meeting started. External media remains separate.');await hydrateGovernedMeetings();}catch(error){showToast(error.message);}};
  window.concludeGovernedMeeting=async function(event,id){event.preventDefault();const v=new FormData(event.currentTarget),text=String(v.get('transcript')),source='00:00:01';try{await api.post(`/meetings/${encodeURIComponent(id)}/conclude`,{transcript:[{time:source,speaker:'Chair',text,confidence:1}],minutes:[{type:'discussion',text,source}],outcomes:[{type:'decision',title:v.get('outcomeTitle'),owner:'Chair',due:new Date(Date.now()+7*86400000).toISOString().slice(0,10),destination:v.get('destination'),source}]});showToast('Draft minutes created for human review.');await hydrateGovernedMeetings();}catch(error){showToast(error.message);}};
  window.reviewMeetingOutcome=async function(id,index,state){const reason=prompt(`Reason for ${state} outcome?`,'Verified against transcript source.');if(!reason?.trim())return;try{await api.post(`/meetings/${encodeURIComponent(id)}/outcomes/${index}/review`,{state,reason:reason.trim()});await hydrateGovernedMeetings();}catch(error){showToast(error.message);}};
  window.publishMeetingMinutes=async function(event,id){event.preventDefault();const v=new FormData(event.currentTarget);try{await api.post(`/meetings/${encodeURIComponent(id)}/minutes/publish`,{reviewerConfirmed:v.get('reviewerConfirmed')==='on',publishReason:v.get('publishReason')});showToast('Immutable meeting minutes published with controlled write-backs.');await hydrateGovernedMeetings();}catch(error){showToast(error.message);}};

  let activeDocumentRevisionId=null,documentRevisions=[],documentReadiness=null;
  const documentTypes=['drawing','specification','appointment','approval_letter','municipal_form','submission_pack','tender_pack','rfi','site_instruction','payment_certificate','closeout_certificate','warranty','closeout_pack'],documentDisciplines=['architectural','structural','civil','electrical','mechanical','fire','quantity_surveying','general'],documentPurposes=['for_review','for_information','for_municipal_submission','for_tender','for_construction','as_built','closeout'],documentSheets=['site_plan','floor_plan','section','elevation','detail','schedule','cover','general'];
  function documentControlWorkspace(){setTimeout(hydrateDocumentControl,0);const active=window.__ARCHITEX_SHELL_STATE__?.projects.find(item=>item.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId);return `${pageHead('Documents & Drawings','Controlled registers, linked revisions, current-set warnings and structured pack readiness.','documents_drawings','core')}
    <section id="documentControlWorkspace" class="document-workspace">
      <div class="notice document-boundary"><b>Evidence boundary:</b> Metadata and workflow decisions are human-entered and reviewed. No OCR, PDF parsing, AI classification or digital signature provider is configured; Architex makes no automated drawing-content or regulatory determination.</div>
      <form id="documentCreateForm" class="panel panel-pad document-create"><div class="trust-card-head"><div><h2>Register controlled document</h2><p>${escapeHtml(active?.name||'Select a project')} · begin with a revision-coded draft.</p></div><span class="status amber">Draft first</span></div><div class="scaffold-grid"><label class="trust-wide">Title<input class="form-input" name="title" required maxlength="220"></label><label>Document type<select class="form-select" name="documentType">${documentTypes.map(x=>`<option value="${x}">${x.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Discipline<select class="form-select" name="discipline">${documentDisciplines.map(x=>`<option value="${x}">${x.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Phase<select class="form-select" name="phase">${communicationPhases.map(x=>`<option value="${x[0]}" ${x[0]===(active?.currentPhase||'design_development')?'selected':''}>${x[1]}</option>`).join('')}</select></label><label>Initial purpose<select class="form-select" name="issuePurpose">${documentPurposes.map(x=>`<option value="${x}">${x.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Revision code<input class="form-input" name="revisionCode" required maxlength="40" value="P01"></label><label>Drawing number<input class="form-input" name="drawingNumber" maxlength="100" value="A-001"></label><label>Sheet type<select class="form-select" name="sheetType">${documentSheets.map(x=>`<option value="${x}">${x.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Scale<input class="form-input" name="scale" maxlength="40" value="1:100"></label><label class="trust-wide">Revision notes<textarea class="form-textarea" name="notes" maxlength="12000" required></textarea></label></div><div class="trust-actions"><button class="btn dark" type="submit">Create controlled draft</button><span id="documentCreateMessage" role="status"></span></div></form>
      <section class="panel panel-pad document-register"><div class="trust-card-head"><div><h2>Document Register</h2><p>All revision states remain visible; current documents are never inferred from filenames.</p></div><button class="btn ghost" type="button" onclick="refreshDocumentControl()">Refresh</button></div><div id="documentRegister" class="trust-list"><div class="notice">Loading documents…</div></div></section>
      <section class="panel panel-pad drawing-register"><div class="trust-card-head"><div><h2>Drawing Register</h2><p>Drawing number, discipline, sheet type, scale, purpose and status are revision-controlled.</p></div></div><div id="drawingRegister" class="trust-list"><div class="notice">Loading drawings…</div></div></section>
      <section class="panel panel-pad document-editor"><div class="trust-card-head"><div><h2>Revision History</h2><p>Draft edits, human review, issue and supersession are separate governed actions.</p></div><span id="documentEditorStatus" class="status">Select revision</span></div><div id="documentRevisionEditor"><div class="notice">Select a document revision.</div></div></section>
      <section class="panel panel-pad document-readiness"><div class="trust-card-head"><div><h2>Pack Readiness</h2><p>Structured workflow checks only—not legal, regulatory or professional approval.</p></div><span class="status amber">Human review</span></div><div id="documentReadiness" class="readiness-grid"><div class="notice">Loading readiness…</div></div></section>
    </section>`;}
  async function hydrateDocumentControl(){const root=document.getElementById('documentControlWorkspace'),projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;if(!root)return;if(!projectId){document.getElementById('documentRegister').innerHTML='<div class="notice">Create or select a project first.</div>';return;}try{[documentRevisions,documentReadiness]=await Promise.all([api.get(`/documents?projectId=${encodeURIComponent(projectId)}`),api.get(`/projects/${encodeURIComponent(projectId)}/document-readiness`)]);if(!documentRevisions.some(x=>x.id===activeDocumentRevisionId))activeDocumentRevisionId=documentRevisions[0]?.id||null;renderDocumentRegisters();renderDocumentRevisionEditor();renderDocumentReadiness();const form=document.getElementById('documentCreateForm');if(form&&!form.dataset.bound){form.dataset.bound='1';form.addEventListener('submit',createControlledDocument);form.elements.documentType.addEventListener('change',toggleDocumentDrawingFields);toggleDocumentDrawingFields();}}catch(error){document.getElementById('documentRegister').innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}
  function toggleDocumentDrawingFields(){const form=document.getElementById('documentCreateForm');if(!form)return;const enabled=form.elements.documentType.value==='drawing';['drawingNumber','sheetType','scale'].forEach(name=>{form.elements[name].disabled=!enabled;form.elements[name].closest('label').classList.toggle('document-field-disabled',!enabled);});}
  function renderDocumentRegisters(){const documents=document.getElementById('documentRegister'),drawings=document.getElementById('drawingRegister');if(!documents||!drawings)return;documents.innerHTML=documentRevisions.length?documentRevisions.map(item=>`<button type="button" class="trust-row document-row ${item.id===activeDocumentRevisionId?'active':''}" onclick="selectDocumentRevision('${escapeHtml(item.id)}')"><div><b>${escapeHtml(item.title)}</b><span>${escapeHtml(item.documentType.replaceAll('_',' '))} · ${escapeHtml(item.revisionCode)} · ${escapeHtml(item.issuePurpose.replaceAll('_',' '))}</span><small>${escapeHtml(item.createdAt)}${item.revisionReason?' · '+escapeHtml(item.revisionReason):''}</small></div><span class="status ${item.status==='issued'||item.status==='approved'?'green':item.status==='superseded'?'':'amber'}">${escapeHtml(item.status.replaceAll('_',' '))}</span></button>`).join(''):'<div class="notice">No controlled documents are registered.</div>';const drawingRows=documentRevisions.filter(x=>x.drawing);drawings.innerHTML=drawingRows.length?drawingRows.map(item=>`<button type="button" class="trust-row document-row ${item.id===activeDocumentRevisionId?'active':''}" onclick="selectDocumentRevision('${escapeHtml(item.id)}')"><div><b>${escapeHtml(item.drawing.drawingNumber)} · ${escapeHtml(item.title)}</b><span>${escapeHtml(item.drawing.discipline)} · ${escapeHtml(item.drawing.sheetType.replaceAll('_',' '))} · ${escapeHtml(item.drawing.scale||'scale not recorded')}</span><small>${escapeHtml(item.drawing.issuePurpose.replaceAll('_',' '))} · revision ${escapeHtml(item.revisionCode)}</small></div><span class="status ${item.drawing.status==='issued'?'green':item.drawing.status==='superseded'?'':'amber'}">${escapeHtml(item.drawing.status.replaceAll('_',' '))}</span></button>`).join(''):'<div class="notice">No drawing revisions are registered.</div>';}
  function renderDocumentRevisionEditor(){const editor=document.getElementById('documentRevisionEditor'),badge=document.getElementById('documentEditorStatus'),item=documentRevisions.find(x=>x.id===activeDocumentRevisionId);if(!editor)return;if(!item){editor.innerHTML='<div class="notice">Select a document revision.</div>';return;}badge.textContent=item.status.replaceAll('_',' ');badge.className=`status ${item.status==='issued'||item.status==='approved'?'green':'amber'}`;const editable=item.status==='draft'||item.status==='issued',lock=editable?'':'disabled';const drawing=item.drawing?`<label>Drawing number<input class="form-input" name="drawingNumber" value="${escapeHtml(item.drawing.drawingNumber)}" required ${lock}></label><label>Sheet type<select class="form-select" name="sheetType" ${lock}>${documentSheets.map(x=>`<option value="${x}" ${x===item.drawing.sheetType?'selected':''}>${x.replaceAll('_',' ')}</option>`).join('')}</select></label><label>Scale<input class="form-input" name="scale" value="${escapeHtml(item.drawing.scale||'')}" ${lock}></label>`:'';let actions='';if(item.status==='draft')actions='<button class="btn ghost" type="submit">Save draft metadata</button><button class="btn dark" type="button" onclick="submitDocumentReview()">Submit for review</button>';if(item.status==='pending_review')actions='<button class="btn dark" type="button" onclick="approveControlledDocument()">Approve exact revision</button>';if(item.status==='approved')actions=`<label>Issue purpose<select class="form-select" name="issuePurpose">${documentPurposes.map(x=>`<option value="${x}" ${x===item.issuePurpose?'selected':''}>${x.replaceAll('_',' ')}</option>`).join('')}</select></label><button class="btn dark" type="button" onclick="issueControlledDocument()">Issue exact revision</button>`;if(item.status==='issued')actions=`<label>New revision code<input class="form-input" name="revisionCode" required value="${escapeHtml(item.revisionCode)}-R1"></label><label class="trust-wide">Revision reason<input class="form-input" name="revisionReason" required value="Coordinated information changed after issue."></label><button class="btn dark" type="button" onclick="reviseControlledDocument()">Create linked revision</button>`;editor.innerHTML=`<form id="documentRevisionForm"><div class="scaffold-grid"><label class="trust-wide">${escapeHtml(item.title)} · ${escapeHtml(item.revisionCode)}<textarea class="form-textarea" name="notes" maxlength="12000" ${editable?'':'readonly'}>${escapeHtml(item.notes)}</textarea></label>${drawing}${actions}</div><div class="document-hash">${item.auditHash?'Issue SHA-256 '+escapeHtml(item.auditHash):'No issue hash until formal issue.'}</div><div id="documentRevisionMessage" role="status"></div></form>`;if(item.status==='draft')document.getElementById('documentRevisionForm').addEventListener('submit',saveControlledDocumentDraft);}
  function renderDocumentReadiness(){const target=document.getElementById('documentReadiness');if(!target||!documentReadiness)return;target.innerHTML=Object.entries(documentReadiness).map(([key,report])=>`<article class="readiness-card"><div class="trust-card-head"><b>${escapeHtml(key.replaceAll('_',' '))}</b><span class="status ${report.ready?'green':'amber'}">${report.ready?'ready':'blocked'}</span></div>${report.findings.length?report.findings.map(f=>`<div class="readiness-finding"><b>${escapeHtml(f.code.replaceAll('_',' '))}</b><p>${escapeHtml(f.message)}</p></div>`).join(''):'<p>No structured blockers.</p>'}</article>`).join('');}
  async function createControlledDocument(event){event.preventDefault();const form=event.currentTarget,v=new FormData(form),message=document.getElementById('documentCreateMessage'),type=v.get('documentType'),body={projectId:window.__ARCHITEX_SHELL_STATE__.selectedProjectId,title:v.get('title'),documentType:type,discipline:v.get('discipline'),phase:v.get('phase'),issuePurpose:v.get('issuePurpose'),revisionCode:v.get('revisionCode'),notes:v.get('notes')};if(type==='drawing')body.drawing={drawingNumber:v.get('drawingNumber'),sheetType:v.get('sheetType'),scale:v.get('scale')};message.textContent='Creating controlled draft…';try{const created=await api.post('/documents',body);activeDocumentRevisionId=created.id;form.reset();message.textContent='Controlled draft created and audited.';await hydrateDocumentControl();}catch(error){message.textContent=error.message;}}
