  let activeFormTemplateId=null,activeFormDraftId=null,formTemplates=[],formDrafts=[];
  function integratedFormWorkspace(){setTimeout(hydrateIntegratedForms,0);const active=window.__ARCHITEX_SHELL_STATE__?.projects.find(item=>item.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId);return `${pageHead('Integrated Form System','Project-aware templates, controlled revisions, human approval and immutable evidence exports.','forms','amber')}
    <section id="integratedFormSystem" class="forms-workspace">
      <div class="notice forms-boundary"><b>Human-governed forms:</b> Auto-fill is a convenience, not verification. Review every field before approval and issue. No PDF or e-signature provider is configured; this release creates checksum-protected HTML and JSON evidence only.</div>
      <section class="panel panel-pad forms-library"><div class="trust-card-head"><div><h2>Template Library</h2><p>Only verified, versioned templates available to this organisation are shown.</p></div><span class="status green">Versioned</span></div><div id="formTemplateLibrary" class="form-template-grid"><div class="notice">Loading templates…</div></div></section>
      <section class="panel panel-pad forms-editor"><div class="trust-card-head"><div><h2>Form Editor</h2><p>${escapeHtml(active?.name||'Select a project')} · auto-fill snapshots remain attached to the exact revision.</p></div><span id="formEditorStatus" class="status">Select template</span></div><div id="formEditor"><div class="notice">Choose a verified template or an existing draft.</div></div></section>
      <section class="panel panel-pad forms-drafts"><div class="trust-card-head"><div><h2>My Drafts</h2><p>Draft, review, approval, issue and supersession states persist in MariaDB.</p></div><button class="btn ghost" type="button" onclick="refreshIntegratedForms()">Refresh</button></div><div id="formDraftList" class="trust-list"><div class="notice">Loading drafts…</div></div></section>
      <section class="panel panel-pad forms-exports"><div class="trust-card-head"><div><h2>Evidence Exports</h2><p>Issued revisions expose immutable HTML and JSON evidence with SHA-256 checksums.</p></div><span class="status amber">No PDF / e-sign</span></div><div id="formExportList" class="trust-list"><div class="notice">Select an issued revision.</div></div></section>
      <section class="panel panel-pad forms-audit"><div class="trust-card-head"><div><h2>Audit history</h2><p>Revision lineage and every controlled state remain visible; earlier versions are never overwritten.</p></div></div><div id="formAuditHistory" class="form-audit-line"><div class="notice">No form history selected.</div></div></section>
    </section>`;}
  async function hydrateIntegratedForms(){const root=document.getElementById('integratedFormSystem'),projectId=window.__ARCHITEX_SHELL_STATE__?.selectedProjectId;if(!root)return;if(!projectId){root.querySelectorAll('button,input,select,textarea').forEach(control=>control.disabled=true);document.getElementById('formEditor').innerHTML='<div class="notice">Create or select a project before creating a governed form.</div>';return;}try{[formTemplates,formDrafts]=await Promise.all([api.get('/form-templates'),api.get(`/form-drafts?projectId=${encodeURIComponent(projectId)}`)]);if(!formTemplates.some(item=>item.id===activeFormTemplateId))activeFormTemplateId=formTemplates[0]?.id||null;if(!formDrafts.some(item=>item.id===activeFormDraftId))activeFormDraftId=null;renderFormTemplateLibrary();renderFormDraftList();await renderFormEditor();}catch(error){document.getElementById('formEditor').innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}
  function renderFormTemplateLibrary(){const list=document.getElementById('formTemplateLibrary');if(!list)return;list.innerHTML=formTemplates.length?formTemplates.map(template=>`<button type="button" class="form-template-card ${template.id===activeFormTemplateId&&!activeFormDraftId?'active':''}" onclick="selectFormTemplate('${escapeHtml(template.id)}')"><span class="status green">${escapeHtml(template.status)}</span><b>${escapeHtml(template.name)}</b><small>${escapeHtml(template.category)} · v${escapeHtml(template.version)}</small><p>${escapeHtml(template.limitations)}</p></button>`).join(''):'<div class="notice">No verified templates are available.</div>';}
  function renderFormDraftList(){const list=document.getElementById('formDraftList');if(!list)return;list.innerHTML=formDrafts.length?formDrafts.map(draft=>`<button type="button" class="trust-row form-draft-row ${draft.id===activeFormDraftId?'active':''}" onclick="selectFormDraft('${escapeHtml(draft.id)}')"><div><b>${escapeHtml(draft.title)}</b><span>${escapeHtml(draft.template.name)} · revision ${draft.revision}</span><small>${escapeHtml(draft.createdAt)}${draft.revisionReason?' · '+escapeHtml(draft.revisionReason):''}</small></div><span class="status ${draft.status==='issued'||draft.status==='approved'?'green':draft.status==='superseded'?'':'amber'}">${escapeHtml(draft.status.replaceAll('_',' '))}</span></button>`).join(''):'<div class="notice">No governed forms have been created for this project.</div>';renderFormAuditHistory();}
  async function renderFormEditor(){const editor=document.getElementById('formEditor'),status=document.getElementById('formEditorStatus');if(!editor)return;const draft=activeFormDraftId?formDrafts.find(item=>item.id===activeFormDraftId):null,template=draft?.template||formTemplates.find(item=>item.id===activeFormTemplateId);if(!template){editor.innerHTML='<div class="notice">No verified template is available.</div>';return;}if(status){status.textContent=draft?draft.status.replaceAll('_',' '):'New draft';status.className=`status ${draft?.status==='issued'||draft?.status==='approved'?'green':'amber'}`;}const project=window.__ARCHITEX_SHELL_STATE__?.projects.find(item=>item.id===window.__ARCHITEX_SHELL_STATE__?.selectedProjectId)||{},autoValues={projectName:project.name||project.projectName||'',projectCode:project.projectCode||'',clientName:project.clientName||'',municipality:project.municipality||'',propertyReference:project.propertyReference||'',propertyUse:project.propertyUse||'',currentPhase:project.currentPhase||'',userEmail:window.__ARCHITEX_SHELL_STATE__?.session?.email||''},values=draft?.values||{},fields=template.fields.map(field=>{const value=draft?(values[field.key]||''):(field.autoFill?autoValues[field.autoFill]||'':'');const control=field.type==='textarea'?`<textarea class="form-textarea" name="${escapeHtml(field.key)}" ${field.required?'required':''}>${escapeHtml(value)}</textarea>`:`<input class="form-input" type="${field.type==='email'?'email':'text'}" name="${escapeHtml(field.key)}" value="${escapeHtml(value)}" ${field.required?'required':''}>`;return `<label class="${field.type==='textarea'?'trust-wide':''}">${escapeHtml(field.label)}${field.autoFill&&!draft?'<small> Auto-filled from project record</small>':''}${control}</label>`;}).join('');const snapshot=draft?`<details class="form-snapshot"><summary>Auto-fill snapshot</summary><pre>${escapeHtml(JSON.stringify(draft.autoFillSnapshot,null,2))}</pre></details>`:'';let actions='';if(!draft)actions='<button class="btn dark" type="submit">Create versioned draft</button>';else if(draft.status!=='superseded'){actions=`<label class="trust-wide">Revision reason<input class="form-input" name="reason" maxlength="500" value="Reviewed field updates for a new immutable revision."></label><button class="btn ghost" type="submit">Create revision</button>${draft.status==='draft'?'<button class="btn dark" type="button" onclick="submitFormReview()">Submit for review</button>':''}${draft.status==='review_required'?'<button class="btn dark" type="button" onclick="approveGovernedForm()">Approve exact revision</button>':''}${draft.status==='approved'?'<button class="btn dark" type="button" onclick="issueGovernedForm()">Issue exact revision</button>':''}`;}editor.innerHTML=`<form id="governedFormEditor"><div class="scaffold-grid"><label class="trust-wide">Form title<input class="form-input" name="title" maxlength="220" required value="${escapeHtml(draft?.title||template.name)}" ${draft?'readonly':''}></label>${fields}${actions}</div><div id="governedFormMessage" role="status"></div></form>${snapshot}`;document.getElementById('governedFormEditor')?.addEventListener('submit',draft?reviseGovernedForm:createGovernedForm);await renderFormExports(draft);}
  function formValues(form,template){const data=new FormData(form),values={};template.fields.forEach(field=>{const value=data.get(field.key);if(value!==null)values[field.key]=value;});return values;}
  async function createGovernedForm(event){event.preventDefault();const form=event.currentTarget,template=formTemplates.find(item=>item.id===activeFormTemplateId),message=document.getElementById('governedFormMessage');message.textContent='Creating versioned draft…';try{const draft=await api.post('/form-drafts',{projectId:window.__ARCHITEX_SHELL_STATE__.selectedProjectId,templateId:template.id,title:new FormData(form).get('title'),values:formValues(form,template)});activeFormDraftId=draft.id;message.textContent='Draft created and audited.';await hydrateIntegratedForms();}catch(error){message.textContent=error.message;}}
