  window.submitFormReview=async function(){const reason=prompt('Reason for professional review?','All required fields are complete and ready for professional review.');if(!reason?.trim())return;try{await api.post(`/form-drafts/${encodeURIComponent(activeFormDraftId)}/submit-review`,{reason:reason.trim()});await hydrateIntegratedForms();}catch(error){showToast(error.message);}};
