  window.issueGovernedForm=async function(){const reason=prompt('Reason for formal issue:','Responsible professional approved this exact revision for issue.');if(!reason?.trim()||!confirm('Issue and lock this exact revision with immutable evidence exports?'))return;try{await api.post(`/form-drafts/${encodeURIComponent(activeFormDraftId)}/issue`,{humanConfirmed:true,reason:reason.trim()});await hydrateIntegratedForms();showToast('Form issued with HTML and JSON evidence.');}catch(error){showToast(error.message);}};
  async function renderFormExports(draft){const list=document.getElementById('formExportList');if(!list)return;if(!draft||draft.status!=='issued'){list.innerHTML='<div class="notice">Select an issued revision to access evidence exports.</div>';return;}try{const exports=await api.get(`/form-drafts/${encodeURIComponent(draft.id)}/exports`);list.innerHTML=exports.map(item=>`<article class="trust-row"><div><b>${escapeHtml(item.format.toUpperCase())} evidence</b><span>SHA-256 ${escapeHtml(item.checksum)}</span><small>${escapeHtml(item.createdAt)}</small></div><button class="btn ghost" type="button" onclick="downloadFormExport('${escapeHtml(item.id)}','${escapeHtml(draft.title)}')">Download</button></article>`).join('');}catch(error){list.innerHTML=`<div class="notice">${escapeHtml(error.message)}</div>`;}}
  function renderFormAuditHistory(){const history=document.getElementById('formAuditHistory');if(!history)return;const selected=formDrafts.find(item=>item.id===activeFormDraftId);if(!selected){history.innerHTML='<div class="notice">Select a revision to inspect its governed history.</div>';return;}const family=formDrafts.filter(item=>item.id===selected.id||item.parentDraftId===selected.id||item.id===selected.parentDraftId).sort((a,b)=>a.revision-b.revision);history.innerHTML=family.map(item=>`<article><span class="form-audit-dot ${item.status}"></span><div><b>Revision ${item.revision} · ${escapeHtml(item.status.replaceAll('_',' '))}</b><p>${escapeHtml(item.revisionReason||item.reviewReason||item.approvalReason||item.issueReason||'Initial draft created.')}</p>${item.auditHash?`<small>SHA-256 ${escapeHtml(item.auditHash)}</small>`:''}</div></article>`).join('');}
